UPDATE MBW_BOOTSTRAP_APPROVAL
   SET STATUS = 'CLAIMED', OPERATION_ID = :operationId, CLAIM_OWNER_ID = :claimOwnerId,
       CLAIMED_AT = UTC_TIMESTAMP(6), CLAIM_EXPIRES_AT = TIMESTAMPADD(MICROSECOND, :leaseDurationMicros, UTC_TIMESTAMP(6)),
       UPDATED_AT = UTC_TIMESTAMP(6)
 WHERE TOKEN_HASH = :tokenHash
   AND ENV_FINGERPRINT = :environmentFingerprint
   AND EXPIRES_AT > UTC_TIMESTAMP(6)
   AND (
        STATUS = 'APPROVED'
        OR (STATUS = 'CLAIMED' AND OPERATION_ID = :operationId AND CLAIM_EXPIRES_AT <= UTC_TIMESTAMP(6))
   )
